const { ref, inject, onMounted, onBeforeUnmount, nextTick } = Vue;

export default {
    setup() {
        const page = ref(0); //0-Main 1-Gameplay 2-Gameover 3-Win
        const timing = ref(0);
        let startTime;
        let timer;
        const backend = inject("backend");

        const prevLine = ref("");
        const currLine = ref("");
        const inputLine = ref("");

        const getInputCharColor = (i) => {
            if (inputLine.value[i] == currLine.value[i]) {
                return "black";
            } else {
                return "red";
            } 
        }

        const formatTime = (second) => {
            let minutes = Math.floor(second / 60);
            let seconds = second % 60;
            return `${minutes.toString().padStart(2, '0')}:${seconds.toString().padStart(2, '0')}`;
        }

        const updateTiming = () => {
            timing.value = 300 - Math.floor((Date.now() - startTime) / 1000);
            if (timing.value <= 0) {
                gameover();
            }
        }

        const onKeydown = async (e) => {
            if (page.value == 0) {
                if (e.key == "Enter") {
                    start();
                }
            } else if (page.value == 1) {
                //playing
                if ("qwertyuiop[]asdfghjkl;'zxcvbnm,./QWERTYUIOP{}ASDFGHJKL:\"ZXCVBNM<>?!@#$%^&*()_+1234567890-=`~".includes(e.key)) {
                    console.log(e.key);
                    let upperLetter = e.key.toUpperCase();
                    inputLine.value += upperLetter;
                } else if (e.key == "Backspace") {
                    inputLine.value = inputLine.value.slice(0, -1);
                } else if (e.key == " ") {
                    inputLine.value += " ";
                } else if (e.key == "Enter") {
                    if (inputLine.value == currLine.value) {
                        prevLine.value = currLine.value;
                        let data = await backend("c15-typing-game", {
                            type: 1,
                            input: inputLine.value
                        });

                        if (data.page == 3) {
                            page.value = 3;
                        } else if (data.page != 1) {
                            gameover();
                        } else {
                            currLine.value = data.text;
                            inputLine.value = "";
                        }
                    }
                } else {
                    console.log("Invalid key");
                }
            } else {
                if (e.key == "Enter") {
                    page.value = 0;
                }
            }
        }

        onMounted(() => {
            window.addEventListener('keydown', onKeydown);
        });

        onBeforeUnmount(() => {
            window.removeEventListener('keydown', onKeydown);
            clearInterval(timer);
        });

        const start = async () => {
            startTime = Date.now();
            timing.value = 300;

            let data = await backend("c15-typing-game", {
                type: 0
            });

            timer = setInterval(() => {
                updateTiming();
            }, 1000);

            page.value = data.page;
            prevLine.value = "";
            currLine.value = data.text;
            inputLine.value = "";
        }

        const gameover = () => {
            clearInterval(timer);
            page.value = 2;
        }

        return {
            page,
            timing,
            formatTime,
            prevLine,
            currLine,
            inputLine,
            getInputCharColor
        }
    }
}

